CREATE EXTENSION IF NOT EXISTS pgcrypto;
-- Production schema mirrors the development SQLite domain tables. Use migrations tooling before production deployment.
CREATE TABLE IF NOT EXISTS organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid REFERENCES organizations(id),display_name text NOT NULL,email text,role text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations(id),title text NOT NULL,mode text NOT NULL,subject jsonb NOT NULL,phenotypes jsonb NOT NULL,variants jsonb NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analyses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES cases(id),agent text NOT NULL,status text NOT NULL,input_json jsonb NOT NULL,result_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid,source text NOT NULL,title text NOT NULL,content text NOT NULL,entity_type text,entity_id text,quality double precision NOT NULL,metadata_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS consents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),subject_id text NOT NULL,agent text NOT NULL,purpose text NOT NULL,data_categories jsonb NOT NULL,status text NOT NULL,expires_at timestamptz,version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS audits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid,event_type text NOT NULL,user_id text,case_id text,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
